/// Real-time pitch detection during recording
Future<void> _startRealtimePitchDetection() async {
  _setupPitchDetectionTimer();
}

void _setupPitchDetectionTimer() {
  _pitchDetectionTimer?.cancel();

  _pitchDetectionTimer = Timer.periodic(const Duration(milliseconds: 100), (timer) {
    if (!mounted || !sessionProvider.isRecording) {
      timer.cancel();
      _pitchDetectionTimer = null;
      return;
    }
    _generateRealtimePitch();
  });
}
