```tsx
import { registerOverlayPortal } from "@measured/puck";

const MyComponent = () => {
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => registerOverlayPortal(ref.current), [ref.current]);

  return <button ref={ref}>Clickable</button>
}
```

